/**
 * Auth Controller — Handles authentication requests.
 * Generated by BackendForge
 */

const authService = require('../services/auth.service');
const { ApiError } = require('../middleware/error-handler.middleware');

const authController = {
  /**
   * POST /api/auth/register — Register a new customer
   */
  async register(req, res, next) {
    try {
      const { name, email, phone, password } = req.body;
      const result = await authService.register({ name, email, phone, password });
      res.status(201).json({
        success: true,
        message: 'Registration successful',
        data: result,
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/auth/login — Customer login
   */
  async login(req, res, next) {
    try {
      const { email, password } = req.body;
      const result = await authService.login(email, password);
      res.json({
        success: true,
        message: 'Login successful',
        data: result,
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/auth/admin/login — Admin login step 1 (validates credentials, sends OTP)
   */
  async adminLogin(req, res, next) {
    try {
      const { email, password } = req.body;
      const result = await authService.adminLoginStep1(email, password);
      res.json({
        success: true,
        message: 'OTP sent to your registered email and phone number',
        data: { userId: result.userId, otpSentTo: result.otpSentTo },
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/auth/admin/verify-otp — Admin login step 2 (verify OTP)
   */
  async verifyAdminOTP(req, res, next) {
    try {
      const { userId, code } = req.body;
      const result = await authService.adminLoginStep2(userId, code);
      res.json({
        success: true,
        message: 'Admin authentication successful',
        data: result,
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/auth/refresh — Refresh access token
   */
  async refreshToken(req, res, next) {
    try {
      const { refreshToken } = req.body;
      if (!refreshToken) throw ApiError.badRequest('Refresh token is required');
      const result = await authService.refreshAccessToken(refreshToken);
      res.json({
        success: true,
        message: 'Token refreshed',
        data: result,
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/auth/forgot-password — Request password reset
   */
  async forgotPassword(req, res, next) {
    try {
      const { email } = req.body;
      await authService.forgotPassword(email);
      res.json({
        success: true,
        message: 'If that email exists, a password reset link has been sent.',
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/auth/reset-password — Reset password with token
   */
  async resetPassword(req, res, next) {
    try {
      const { token, newPassword } = req.body;
      await authService.resetPassword(token, newPassword);
      res.json({
        success: true,
        message: 'Password reset successful. Please login with your new password.',
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * POST /api/auth/logout — Logout (blacklist token)
   */
  async logout(req, res, next) {
    try {
      const token = req.headers.authorization?.split(' ')[1];
      await authService.logout(req.userId, token);
      res.json({
        success: true,
        message: 'Logged out successfully',
      });
    } catch (error) {
      next(error);
    }
  },

  /**
   * GET /api/auth/me — Get current authenticated user
   */
  async getCurrentUser(req, res, next) {
    try {
      res.json({
        success: true,
        data: { user: req.user },
      });
    } catch (error) {
      next(error);
    }
  },
};

module.exports = authController;
